// types.mjs — shared value model mirroring what Python's yaml.safe_load() produces.
// All modules (resolver, parser, emitter) build on these classes.
// Pure ESM, no external imports, no RegExp, no JSON.

export class YamlError extends Error {
  constructor(message) {
    super(message);
    this.name = 'YamlError';
  }
}

// Python datetime.date
export class YamlDate {
  constructor(year, month, day) {
    this.year = year;     // int
    this.month = month;   // int 1-12
    this.day = day;       // int 1-31
  }
}

// Python datetime.datetime. tzOffsetMinutes === null means "naive" (no timezone).
export class YamlDateTime {
  constructor(year, month, day, hour, minute, second, microsecond = 0, tzOffsetMinutes = null) {
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;         // int 0..999999
    this.tzOffsetMinutes = tzOffsetMinutes; // int (minutes east of UTC) or null
  }
}

// Python bytes produced by the !!binary constructor.
export class YamlBinary {
  constructor(bytes /* Uint8Array */) {
    this.bytes = bytes;
  }
}

function padNum(n, width) {
  let s = String(n);
  while (s.length < width) s = '0' + s;
  return s;
}

// 'YYYY-MM-DD HH:MM:SS[.ffffff][+HH:MM]' — Python datetime.isoformat(sep=' ')
export function dateTimeToString(dt) {
  let s = padNum(dt.year, 4) + '-' + padNum(dt.month, 2) + '-' + padNum(dt.day, 2);
  if (dt instanceof YamlDateTime) {
    s += ' ' + padNum(dt.hour, 2) + ':' + padNum(dt.minute, 2) + ':' + padNum(dt.second, 2);
    if (dt.microsecond !== 0) s += '.' + padNum(dt.microsecond, 6);
    if (dt.tzOffsetMinutes !== null) {
      const sign = dt.tzOffsetMinutes < 0 ? '-' : '+';
      const abs = Math.abs(dt.tzOffsetMinutes);
      s += sign + padNum(Math.floor(abs / 60), 2) + ':' + padNum(abs % 60, 2);
    }
  }
  return s;
}

// Normalize a JS key the way a Python dict would treat it (True == 1 == 1.0,
// None distinct, etc.) so duplicate-key handling matches CPython semantics.
function normalizeKey(key) {
  if (key === null) return 'null:';
  if (typeof key === 'boolean') return 'num:' + (key ? 1 : 0);
  if (typeof key === 'number') return 'num:' + key;
  if (typeof key === 'bigint') return 'num:' + key.toString();
  if (typeof key === 'string') return 'str:' + key;
  if (key instanceof YamlDateTime) return 'dt:' + dateTimeToString(key);
  if (key instanceof YamlDate) return 'date:' + dateTimeToString(key);
  throw new YamlError('found unhashable key');
}

// Insertion-ordered mapping with Python dict semantics: setting an existing
// key replaces the value but keeps the original key object and position.
export class YamlMap {
  constructor() {
    this._slots = new Map(); // normKey -> [origKey, value]
    this._order = [];        // normKeys in first-insertion order
  }
  set(key, value) {
    const norm = normalizeKey(key);
    if (this._slots.has(norm)) {
      this._slots.get(norm)[1] = value;
    } else {
      this._slots.set(norm, [key, value]);
      this._order.push(norm);
    }
  }
  get(key) {
    const slot = this._slots.get(normalizeKey(key));
    return slot ? slot[1] : undefined;
  }
  has(key) {
    return this._slots.has(normalizeKey(key));
  }
  get size() {
    return this._order.length;
  }
  // Array of [origKey, value] pairs in insertion order.
  entries() {
    return this._order.map((k) => this._slots.get(k));
  }
}

// Python's sorted() comparison for mapping keys (yaml.dump sorts keys by
// default). Mixed incomparable types throw, like CPython's TypeError.
export function pythonKeyCompare(a, b) {
  const rank = (v) => {
    if (typeof v === 'boolean') return 0;
    if (typeof v === 'number' || typeof v === 'bigint') return 0;
    if (typeof v === 'string') return 1;
    if (v instanceof YamlDateTime) return 2;
    if (v instanceof YamlDate) return 3;
    if (v === null) return 4;
    return 5;
  };
  const ra = rank(a);
  const rb = rank(b);
  if (ra !== rb) throw new YamlError("'<' not supported between instances of mapping keys");
  if (ra === 0) {
    const na = typeof a === 'boolean' ? (a ? 1 : 0) : Number(a);
    const nb = typeof b === 'boolean' ? (b ? 1 : 0) : Number(b);
    return na < nb ? -1 : na > nb ? 1 : 0;
  }
  if (ra === 1) return a < b ? -1 : a > b ? 1 : 0;
  if (ra === 2 || ra === 3) {
    const sa = dateTimeToString(a);
    const sb = dateTimeToString(b);
    return sa < sb ? -1 : sa > sb ? 1 : 0;
  }
  return 0;
}
